{"content":"import { useEffect, useRef } from 'react';
import type * as THREE from 'three';
import { useGameStore } from '../store/gameStore';
import { useAimStore } from '../store/aimStore';
import { evaluateShotResult } from '../game-logic/rules';
import type { ShotEvaluationInput } from '../game-logic/rules';
import type { Vec3Tuple } from '../types';
import { MAX_IMPULSE } from '../constants/physics';

// ─────────────────────────────────────────────────────────────────────────────
// Ball API registry — physics bodies register their cannon-es API handles
// here so the shot sequence can apply impulses to the cue ball.
// ─────────────────────────────────────────────────────────────────────────────

export interface BallPhysicsApi {
  applyImpulse: (impulse: Vec3Tuple) => void;
  position: { subscribe: (cb: (v: Vec3Tuple) => void) => () => void };
  velocity: { subscribe: (cb: (v: Vec3Tuple) => void) => () => void };
}

const ballApis = new Map<number, BallPhysicsApi>();

export function registerBallApi(id: number, api: BallPhysicsApi): void {
  ballApis.set(id, api);
}

export function unregisterBallApi(id: number): void {
  ballApis.delete(id);
}

/**
 * Get the physics API for a ball (used by other systems).
 */
export function getBallApi(id: number): BallPhysicsApi | undefined {
  return ballApis.get(id);
}

// ─────────────────────────────────────────────────────────────────────────────
// Shot sequence orchestrator
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Hook that orchestrates the full shot lifecycle:
 *
 * 1. Listens for mouse/keyboard input to drive phase transitions
 *    (IDLE → AIMING → POWER → SIMULATING)
 * 2. Applies the cue-ball impulse on shoot
 * 3. After settle detection transitions to EVALUATING, runs the rules engine
 * 4. Applies evaluation results (fouls, group assignment, game over, next turn)
 *
 * Also integrates the useAim hook for camera-based raycasting on mousemove.
 */
export default function useShotSequence(): void {
  const evaluatedRef = useRef(false);

  // ── Watch for EVALUATING phase and run rules ────────────────────────────
  useEffect(() => {
    let frameId: ReturnType<typeof requestAnimationFrame>;

    const tick = () => {
      const state = useGameStore.getState();

      if (state.phase === 'EVALUATING' && !evaluatedRef.current) {
        evaluatedRef.current = true;

        // Determine if this is the break shot
        const isBreak = state.pocketedBalls.length === 0 && state.shotHistory.length === 0;

        // Build evaluation input using current store state
        // allPocketedBalls: balls pocketed BEFORE this shot
        const allPocketedBeforeShot = state.shotHistory.length > 0
          ? state.shotHistory[0].state.pocketedBalls
          : [];

        const input: ShotEvaluationInput = {
          currentPlayer: state.currentPlayer,
          playerGroups: { ...state.playerGroups },
          pocketedThisShot: [...state.ballsPocketedThisShot],
          firstContact: state.firstContact,
          railContact: state.railContacted,
          allPocketedBalls: allPocketedBeforeShot,
          isBreak,
        };

        const result = evaluateShotResult(input);

        // ── Apply results to store ────────────────────────────────────────

        // Foul
        if (result.foul) {
          useGameStore.getState().setFoul(result.foul);
        }

        // Group assignment
        if (result.assignGroup) {
          useGameStore.getState().assignGroups(
            result.assignGroup.player,
            result.assignGroup.group,
          );
        }

        // Game over
        if (result.gameOver && result.winner !== null) {
          useGameStore.getState().setGameOver(result.winner);
          evaluatedRef.current = false;
          return; // stop processing
        }

        // Ball-in-hand
        if (result.ballInHand) {
          useGameStore.getState().setBallInHand(true);
        }

        // Transition to next turn
        useGameStore.getState().nextTurn(result.nextPlayer);

        // Reset aim power for next shot
        useAimStore.getState().resetPower();

        // Reset evaluation guard after a short delay to allow state to settle
        setTimeout(() => {
          evaluatedRef.current = false;
        }, 100);
      }

      frameId = requestAnimationFrame(tick);
    };

    frameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameId);
  }, []);

  // ── Input handling: mouse & keyboard ────────────────────────────────────
  useEffect(() => {
    const canvas = document.querySelector('canvas');
    if (!canvas) return;

    // ── Helpers for raycasting from camera to Y=0 plane ──────────────────
    // We lazily import THREE to avoid requiring it at module level in this hook
    let raycaster: THREE.Raycaster | null = null;
    let plane: THREE.Plane | null = null;
    let vec2: THREE.Vector2 | null = null;
    let vec3: THREE.Vector3 | null = null;

    const getThreeObjects = async () => {
      if (raycaster) return;
      const THREE = await import('three');
      raycaster = new THREE.Raycaster();
      plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
      vec2 = new THREE.Vector2();
      vec3 = new THREE.Vector3();
    };

    // Pre-initialize
    getThreeObjects();

    /**
     * Compute aim direction from mouse position via camera raycasting.
     * Falls back to simple NDC-based mapping if Three.js not ready.
     */
    const computeAimFromMouse = (e: MouseEvent): Vec3Tuple | null => {
      const rect = canvas.getBoundingClientRect();
      const ndcX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      const ndcY = -((e.clientY - rect.top) / rect.height) * 2 + 1;

      const store = useGameStore.getState();
      const cuePos = store.cueBallPosition;

      if (raycaster && plane) {
        // Camera-based raycasting onto Y=0 table plane
        vec2.set(ndcX, ndcY);

        // Get camera from the R3F store — we access it through a global reference
        // set by the Scene component
        const camera = (window as any).__r3f_camera as THREE.Camera;
        if (camera) {
          raycaster.setFromCamera(vec2, camera);
          const hit = raycaster.ray.intersectPlane(plane, vec3);
          if (hit) {
            const dx = hit.x - cuePos[0];
            const dz = hit.z - cuePos[2];
            const len = Math.sqrt(dx * dx + dz * dz);
            if (len > 0.001) {
              return [dx / len, 0, dz / len];
            }
          }
        }
      }

      // Fallback: simple NDC angle-based aim
      const angle = ndcX * Math.PI;
      return [Math.sin(angle), 0, Math.cos(angle)];
    };

    // ── Mouse down ───────────────────────────────────────────────────────
    const handleMouseDown = (e: MouseEvent) => {
      // Ignore right-click
      if (e.button !== 0) return;

      const { phase, ballInHand } = useGameStore.getState();

      // Ball-in-hand placement
      if (ballInHand && phase === 'IDLE') {
        const rect = canvas.getBoundingClientRect();
        const ndcX = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        const ndcY = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        // Map NDC to approximate table coordinates
        const x = ndcX * 0.56; // HALF_WIDTH
        const z = -ndcY * 1.12; // HALF_LENGTH

        useGameStore.getState().placeBallInHand([x, 0.0285, z]);
        return;
      }

      if (phase === 'IDLE') {
        // IDLE → AIMING
        const aimDir = computeAimFromMouse(e);
        if (aimDir) {
          useAimStore.getState().setDirection(aimDir);
        }
        useGameStore.getState().startAiming();
      } else if (phase === 'AIMING') {
        // AIMING → POWER (start charging)
        useGameStore.getState().startPower();
        useAimStore.getState().startCharging();
      }
    };

    // ── Mouse up ─────────────────────────────────────────────────────────
    const handleMouseUp = (e: MouseEvent) => {
      if (e.button !== 0) return;

      const { phase } = useGameStore.getState();
      const { power, direction, isCharging } = useAimStore.getState();

      if (phase === 'POWER' && isCharging) {
        // Calculate impulse vector
        const impulseMagnitude = power * MAX_IMPULSE;
        const impulse: Vec3Tuple = [
          direction[0] * impulseMagnitude,
          0,
          direction[2] * impulseMagnitude,
        ];

        // Apply impulse to the cue ball via physics API
        const cueApi = ballApis.get(0);
        if (cueApi) {
          cueApi.applyImpulse(impulse);
        }

        // Transition store: POWER → SIMULATING (also takes snapshot internally)
        useGameStore.getState().shoot(impulse);
        useAimStore.getState().stopCharging();
      }
    };

    // ── Mouse move: update aim direction during AIMING/POWER ─────────────
    const handleMouseMove = (e: MouseEvent) => {
      const { phase } = useGameStore.getState();
      if (phase !== 'AIMING' && phase !== 'POWER' && phase !== 'IDLE') return;

      const aimDir = computeAimFromMouse(e);
      if (aimDir) {
        useAimStore.getState().setDirection(aimDir);
      }
    };

    // ── Keyboard shortcuts ───────────────────────────────────────────────
    const handleKeyDown = (e: KeyboardEvent) => {
      // Undo (U)
      if (e.key === 'u' || e.key === 'U') {
        const snapshot = useGameStore.getState().undo();
        if (snapshot) {
          useGameStore.getState().restoreSnapshot(snapshot);
          useAimStore.getState().resetPower();
        }
      }

      // Camera toggle (T)
      if (e.key === 't' || e.key === 'T') {
        useAimStore.getState().toggleCameraMode();
      }

      // Reset game (R)
      if (e.key === 'r' || e.key === 'R') {
        useGameStore.getState().resetGame();
        useAimStore.getState().resetPower();
      }
    };

    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);
}","end_line":303,"start_line":0,"total_lines":304}

{"content":"import { useRef, useEffect, useMemo } from 'react';
import { useSphere } from '@react-three/cannon';
import type { BallId, Vec3Tuple } from '../types';
import { BALL_RADIUS, POCKET_POSITIONS, POCKET_RADIUS } from '../constants/table';
import {
  BALL_MASS,
  LINEAR_DAMPING,
  ANGULAR_DAMPING,
  BALL_BALL_FRICTION,
  BALL_BALL_RESTITUTION,
} from '../constants/physics';
import { useGameStore } from '../store/gameStore';
import { distance } from '../utils/vector';
import { generateBallTexture } from '../utils/textures';
import { registerBallApi, unregisterBallApi } from '../hooks/useShotSequence';
import {
  registerVelocityProvider,
  unregisterVelocityProvider,
} from '../hooks/useSettleDetector';
import * as THREE from 'three';

interface BallBodyProps {
  id: BallId;
  initialPosition: Vec3Tuple;
}

export default function BallBody({ id, initialPosition }: BallBodyProps) {
  const meshRef = useRef<THREE.Mesh>(null);
  const pocketedRef = useRef(false);

  const texture = useMemo(() => {
    const canvas = generateBallTexture(id);
    const tex = new THREE.CanvasTexture(canvas);
    tex.colorSpace = THREE.SRGBColorSpace;
    return tex;
  }, [id]);

  const [, api] = useSphere<THREE.Mesh>(() => ({
    mass: BALL_MASS,
    position: initialPosition,
    args: [BALL_RADIUS],
    material: {
      friction: BALL_BALL_FRICTION,
      restitution: BALL_BALL_RESTITUTION,
    },
    linearDamping: LINEAR_DAMPING,
    angularDamping: ANGULAR_DAMPING,
  }));

  // Register ball API for shot sequence impulse application
  useEffect(() => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- useSphere API type doesn't expose applyImpulse in its TS defs
  registerBallApi(id, api as any);
    return () => unregisterBallApi(id);
  }, [api, id]);

  // Register velocity provider for settle detection
  useEffect(() => {
    let currentVelocity: Vec3Tuple = [0, 0, 0];

    const unsubVelocity = api.velocity.subscribe((v: [number, number, number]) => {
      currentVelocity = v;
    });

    const provider = () => currentVelocity;
    registerVelocityProvider(id, provider);

    return () => {
      unregisterVelocityProvider(id);
      unsubVelocity();
    };
  }, [api, id]);

  // Subscribe to position for pocket detection and state tracking
  useEffect(() => {
    const unsub = api.position.subscribe((pos: [number, number, number]) => {
      if (meshRef.current) {
        meshRef.current.position.set(pos[0], pos[1], pos[2]);
      }

      // Update ball state in store
      const store = useGameStore.getState();
      if (!store.ballStates[id]?.pocketed) {
        // We don't call updateBallState every frame to avoid excessive renders
        // Only update position in ballStates for cue ball (id 0) tracking
        if (id === 0) {
          store.updateBallState(id, pos, store.ballStates[id]?.velocity ?? [0, 0, 0]);
        }
      }

      // Pocket detection during simulation
      const { phase } = useGameStore.getState();
      if (phase === 'SIMULATING' && !pocketedRef.current) {
        for (const pocketPos of POCKET_POSITIONS) {
          const dist = distance(pos, pocketPos);
          if (dist < POCKET_RADIUS) {
            pocketedRef.current = true;
            useGameStore.getState().pocketBall(id);
            // Remove ball from play (drop below table)
            useGameStore.getState().removeBallFromPlay(id);
            api.position.set(pos[0], -0.5, pos[2]);
            api.velocity.set(0, 0, 0);
            api.angularVelocity.set(0, 0, 0);
            break;
          }
        }
      }
    });
    return unsub;
  }, [api, id]);

  // Collision detection for first contact tracking
  useEffect(() => {
    // cannon-es `onCollide` fires when this body contacts another
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const unsub = (api as any).onCollide?.(() => {
      const { phase, firstContact } = useGameStore.getState();
      if (phase !== 'SIMULATING') return;

      // Determine the other ball's id from the collision event
      // cannon-es bodies created by @react-three/cannon don't have a
      // reliable "name" by default, so we use the ball API registry
      // to map bodies to IDs. As a simpler approach, we use a dedicated
      // collision tracking system.

      // For the cue ball (id 0), we track first contact with any object ball
      if (id === 0 && firstContact === null) {
        // The collision event from cannon-es includes e.body which is the
        // other body. We need to identify which ball it is.
        // @react-three/cannon doesn't expose a clean body→id mapping,
        // so we use the position-based approach: check which ball is closest
        // to the cue ball at the moment of collision.

        const store = useGameStore.getState();
        const cuePos = store.ballStates[0]?.position;
        if (!cuePos) return;

        let closestId: BallId | null = null;
        let closestDist = Infinity;

        for (let ballId = 1; ballId <= 15; ballId++) {
          const ballState = store.ballStates[ballId as BallId];
          if (!ballState || ballState.pocketed) continue;

          const dx = cuePos[0] - ballState.position[0];
          const dz = cuePos[2] - ballState.position[2];
          const dist = Math.sqrt(dx * dx + dz * dz);

          if (dist < closestDist) {
            closestDist = dist;
            closestId = ballId as BallId;
          }
        }

        // Only register if close enough (within 2 ball diameters)
        if (closestId !== null && closestDist < BALL_RADIUS * 4) {
          useGameStore.getState().setFirstContact(closestId);
        }
      }
    });

    return () => {
      if (typeof unsub === 'function') unsub();
    };
  }, [api, id]);

  return (
    <mesh ref={meshRef} position={initialPosition} castShadow receiveShadow>
      <sphereGeometry args={[BALL_RADIUS, 32, 32]} />
      <meshStandardMaterial
        map={texture}
        roughness={0.15}
        metalness={0.05}
      />
    </mesh>
  );
}","end_line":176,"start_line":0,"total_lines":177}

{"content":"import type { BallId, Vec3Tuple } from '../types';
import { POCKET_POSITIONS, POCKET_RADIUS } from '../constants/table';
import { distanceSq } from '../utils/vector';

/** Pre-computed squared pocket radius threshold to avoid repeated multiplication */
const POCKET_RADIUS_SQ = POCKET_RADIUS * POCKET_RADIUS;

/**
 * Check if any balls are within pocket zones
 * Returns list of ball IDs that should be pocketed
 */
export function detectPocketedBalls(
  ballPositions: Record<number, Vec3Tuple>,
  alreadyPocketed: Set<number>
): BallId[] {
  const pocketed: BallId[] = [];

  for (const [idStr, pos] of Object.entries(ballPositions)) {
    const id = Number(idStr) as BallId;
    if (alreadyPocketed.has(id)) continue;

    for (const pocketPos of POCKET_POSITIONS) {
      if (distanceSq(pos, pocketPos) < POCKET_RADIUS_SQ) {
        pocketed.push(id);
        break;
      }
    }
  }

  return pocketed;
}

/**
 * Check if a single position is within any pocket zone
 */
export function isInPocket(pos: Vec3Tuple): boolean {
  for (const pocketPos of POCKET_POSITIONS) {
    if (distanceSq(pos, pocketPos) < POCKET_RADIUS_SQ) return true;
  }
  return false;
}","end_line":40,"start_line":0,"total_lines":41}

